INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62169741', 62169741, 'analyze_legacy', 'Mahkamah Agung', 'central', 'PENGADILAN NEGERI SURABAYA 03', 'PENGADAAN LEMBAGA PENYEDIA PEMBERI JASA HUKUM PADA POS BANTUAN HUKUM (POSBAKUM) PENGADILAN NEGERI SURABAYA KELAS I A KHUSUS TAHUN ANGGARAN 2026', 'Jasa Konsultansi', 'Pengadaan Langsung', 'Jawa Timur, Surabaya (Kota)', 96000000, 'January 2025', 'APBN - RUPIAH MURNI (A)', 1, 1, '( 960, OJ, @ 100000 )', '1. Pemberian informasi, konsultasi dan advis hukum secara cuma-cuma. 2. Bantuan pembuatan dokumen hukum yang dibutuhkan secara cuma-cuma. 3. Penyediaan informasi daftar Organisasi Bantuan Hukum sebagaimana dimaksud dalam Undang-Undang Nomor 16 Tahun 2011 tentang Bantuan Hukum, atau Organisasi Bantuan Hukum atau advokat lainnya yang dapat memberikan bantuan hukum cuma-cuma.', 'a. Berbentuk Badan Hukum (Dibuktikan dengan Akta Notaris, terdaftar di Kementerian Hukum dan HAM dan/atau izin mendirikan dari Rektor bagi Perguruan Tinggi). b. Memiliki Pengalaman dalam menangani perkara dan/atau beracara di Pengadilan Negeri. c. Memiliki minimal 2 (dua) orang Advokat dengan pengalaman minimal 2 (dua) tahun. d. Memiliki Struktur organisasi dan/atau kepengurusan yang jelas (Dibuktikan dengan Susunan Organisasi). e. Memiliki minimal 2 (dua) orang staf atau anggota yang akan ditugaskan di Pos Bantuan Hukum, yang berpendidikan minimal Sarjana Hukum (Dibuktikan dengan Ijazah) berpengalaman minimal 1 (satu) tahun. f. Apabila menyertakan mahasiswa untuk bertugas di Pos Bantuan Hukum, harus telah menempuh 140 SKS dan lulus mata kuliah Hukum Acara serta Praktek Hukum Acara dan selama bertugas ada di bawah pengawasan seorang Advokat atau Sarjana Hukum. g. Memiliki Nomor Pokok Wajib Pajak (NPWP) atas nama organisasi. h. Memiliki Rekening bank atas nama organisasi. i. Bersedia menandatangani Pakta Integritas. j. Berdomisili di wilayah hukum Pengadilan Negeri Surabaya Kelas I A Khusus. k. Terdaftar di LPSE dan SIKAP (Dibuktikan dengan screenshot LPSE dan SIKAP).', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 290159);
