INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62203553', 62203553, 'analyze_legacy', 'Provinsi Banten', 'provinsi', 'UPTD Pengelolaan Pendapatan Daerah Rangkasbitung', 'Belanja Alat/Bahan untuk Kegiatan Kantor-Alat Listrik Sub Keg Penyediaan Komponen Instalasi Listrik/Penerangan Bangunan Kantor', 'Barang', 'E-Purchasing', 'Banten, Lebak (Kab.)', 49967000, 'January 2026', 'APBD', 1, 1, '1 Paket', 'Belanja Alat/Bahan untuk Kegiatan Kantor-Alat Listrik Sub Keg Penyediaan Komponen Instalasi Listrik/Penerangan Bangunan Kantor', 'Belanja Alat/Bahan untuk Kegiatan Kantor-Alat Listrik Sub Keg Penyediaan Komponen Instalasi Listrik/Penerangan Bangunan Kantor', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 290384);
INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('64433555', 64433555, 'analyze_legacy', 'Kementerian Perhubungan', 'central', 'UNIT PENYELENGGARA BANDAR UDARA RAHADI OESMAN DI KETAPANG', 'Belanja Pemeliharaan Gedung dan Bangunan (Gedung Terminal) 1800 M2', 'Pekerjaan Konstruksi', 'Penunjukan Langsung', 'Kalimantan Barat, Ketapang (Kab.)', 180000000, 'January 2026', 'APBN - PNBP (D)', 1, 1, '1800 M2', 'Uraian Pekerjaan Detail Belanja Pemeliharaan Gedung Terminal** 1. Pekerjaan Pengecatan Dinding a. Pekerjaan Plamir Pembersihan permukaan dinding dari debu, kotoran, minyak, dan sisa cat lama. Penutupan retak rambut, lubang paku, dan ketidakteraturan permukaan menggunakan bahan plamir. Pengamplasan hasil plamir hingga permukaan dinding rata dan halus. Pembersihan ulang permukaan dinding sebelum proses pengecatan. b. Pekerjaan Pengecatan Dinding Dalam Aplikasi cat dasar (primer/sealer) pada dinding interior. Pengecatan dinding dalam menggunakan cat interior berkualitas sesuai spesifikasi teknis. Pengecatan dilakukan minimal dua lapis hingga warna merata dan rapi. Perlindungan terhadap lantai, plafon, dan elemen lain selama pekerjaan pengecatan. c. Pekerjaan Pengecatan Dinding Luar Pembersihan permukaan dinding eksterior dari lumut, jamur, dan kotoran. Aplikasi cat dasar khusus eksterior bila diperlukan. Pengecatan dinding luar menggunakan cat eksterior tahan cuaca dan sinar UV. Pengecatan dilakukan minimal dua lapis dengan hasil rapi dan merata. 2. Pekerjaan Pengecatan Kusen Pembersihan kusen dari karat, cat lama yang mengelupas, dan kotoran. Pengamplasan permukaan kusen hingga halus. Aplikasi cat dasar (anti karat untuk kusen logam). Pengecatan kusen menggunakan cat sesuai jenis bahan (kayu/besi/aluminium) minimal dua lapis. Perapihan dan pembersihan area sekitar kusen setelah pekerjaan selesai. 3. Pekerjaan Kelistrikan a. Pemasangan Instalasi Lampu 23 Watt Penyediaan dan pemasangan armatur dan lampu LED 23 watt sesuai spesifikasi. Penarikan dan penyambungan kabel instalasi ke jaringan listrik eksisting. Pengujian fungsi lampu setelah pemasangan. b. Pemasangan Instalasi Lampu 14 Watt Penyediaan dan pemasangan armatur dan lampu LED 14 watt. Penyambungan instalasi listrik sesuai standar keselamatan. Pengujian fungsi dan kerapihan pemasangan. c. Pekerjaan dan Pemasangan Stopkontak Penyediaan stopkontak sesuai standar SNI. Pemasangan stopkontak pada titik yang telah ditentukan. Penarikan dan penyambungan kabel ke panel listrik. Pengujian fungsi dan keamanan stopkontak. d. Pekerjaan dan Pemasangan Saklar Penyediaan dan pemasangan saklar sesuai spesifikasi. Penyambungan kabel instalasi ke lampu dan jaringan listrik. Pengujian fungsi saklar dan kerapihan hasil pemasangan. 4. Pekerjaan Pemasangan Lisplank Pengukuran dan penyesuaian ukuran lisplank sesuai lokasi pemasangan. Pemasangan lisplank pada bagian tepi atap atau plafon. Perapihan sambungan dan finishing agar rapi dan estetis. Pengecatan lisplank bila diperlukan. 5. Pekerjaan Pelapisan Pintu HPL Pembersihan permukaan pintu dari kotoran dan lapisan lama. Pengukuran dan pemotongan HPL sesuai ukuran daun pintu. Pemasangan HPL menggunakan lem khusus yang sesuai spesifikasi. Perapihan tepi dan sudut pintu. Pembersihan akhir setelah pekerjaan selesai.', 'pesifikasi Teknis Pekerjaan Belanja Pemeliharaan Gedung Terminal** 1. Pekerjaan Pengecatan Dinding a. Pekerjaan Plamir Bahan plamir siap pakai, kualitas pabrikan. Daya rekat baik, tidak mudah retak atau mengelupas. Permukaan akhir halus dan rata. Aplikasi sesuai petunjuk pabrikan. b. Pekerjaan Pengecatan Dinding Dalam Cat tembok interior kualitas menengah–tinggi. Tahan jamur dan tidak mudah pudar. Warna sesuai persetujuan PPK. Pengecatan minimal 2 (dua) lapis dengan hasil rata dan rapi. c. Pekerjaan Pengecatan Dinding Luar Cat eksterior tahan cuaca dan sinar UV. Tahan terhadap hujan dan perubahan suhu. Warna sesuai persetujuan PPK. Pengecatan minimal 2 (dua) lapis. 2. Pekerjaan Pengecatan Kusen Cat sesuai jenis kusen (kayu/besi/aluminium). Untuk kusen besi menggunakan cat dasar anti karat. Cat memiliki daya rekat baik dan tahan lama. Pengecatan minimal 2 (dua) lapis. 3. Pekerjaan Kelistrikan a. Pemasangan Instalasi Lampu 23 Watt Lampu LED 23 watt, hemat energi. Tegangan kerja 220–240 Volt. Umur pakai minimal 15.000 jam. Armatur dan kabel sesuai standar SNI. b. Pemasangan Instalasi Lampu 14 Watt Lampu LED 14 watt, hemat energi. Tegangan kerja 220–240 Volt. Umur pakai minimal 15.000 jam. Pemasangan rapi dan aman. c. Pekerjaan dan Pemasangan Stopkontak Stopkontak standar SNI. Tegangan 220–240 Volt. Dilengkapi pengaman arde (grounding). Pemasangan tertanam/permukaan sesuai kondisi lapangan. d. Pekerjaan dan Pemasangan Saklar Saklar standar SNI. Daya sesuai beban lampu terpasang. Pemasangan rapi dan mudah dioperasikan. 4. Pekerjaan Pemasangan Lisplank Bahan lisplank dari PVC/kayu/metal sesuai spesifikasi teknis. Tahan terhadap cuaca dan kelembaban. Sambungan rapi dan kuat. Finishing halus dan seragam. 5. Pekerjaan Pelapisan Pintu HPL HPL kualitas menengah–tinggi. Ketebalan minimal 0,8 mm. Tahan gores dan mudah dibersihkan. Pemasangan menggunakan lem khusus HPL. Finishing rapi tanpa gelembung. Ketentuan Umum Seluruh material baru dan belum pernah digunakan. Pelaksanaan pekerjaan mengikuti standar keselamatan kerja. Hasil pekerjaan harus rapi, bersih, dan berfungsi baik. Pekerjaan dinyatakan selesai setelah disetujui PPK.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 290385);
