INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62169673', 62169673, 'analyze_legacy', 'Kementerian Kesehatan', 'central', 'BALAI LABORATORIUM KESEHATAN MASYARAKAT BANJARNEGARA', 'Pemeliharaan gedung/bangunan', 'Jasa Lainnya', 'Pengadaan Langsung', 'Jawa Tengah, Banjarnegara (Kab.)', 199381000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1 Paket', '1. Belanja Pemeliharaan Gedung dan Bangunan berupa : - Pemeliharaan halaman seluas 3.031 M2 x 9,000 = 27.279.000 pekerjaan : perbaikan penerangan halaman, perbaikan jalan di halaman, dan pemeliharaan kondisi lapangan halaman - Pemeliharaan gedung bertingkat seluas 1.266 M2 x 95.000 = 120.270.000 Pekerjaan : perbaikan sarpras terkait gedung laboratorium, atap, pengecatan, perbaikan saluran air dan kebersihan dll - Pemeliharaan gedung tidak bertingka seluas 836 M2 x 62.000 = 51.832.0000 Pekerjaan : Perbaikan sarpras terkait gedung kantor tidak bertingkat, atap, saluran air, gudang dll', 'Kegiatan pemeliharaan gedung/bangunan ini diperlukan karena gedung kantor Balai Labkesmas Banjarnegara terdiri dari Halaman seluas 3.031 m2 , Gedung tidak bertingkat seluas 836 m2 dan Gedung bertingkat 1.266 m2 setiap tahunnya membutuhkan perawatan. Kegiatan perawatan gedung kantor akan membuat umur bangunan tersebut menjadi lebih panjang, ditinjau dari aspek : kekuatan, keamanan, dan penampilan (performance) bangunan. Tujuan dan manfaat dari kegiatan ini adalah terciptanya ruang kerja yang representatif, baik dan memadai. Selain itu terdapat kegiatan pembelian perlengkapan penerangan bangunan meliputi pengadaan perlengkapan penerangan bangunan (lampu indoor dan outdoor) untuk memastikan ketersediaan cahaya yang memadai, menunjang kelancaran operasional, serta meningkatkan kenyamanan, keamanan dan produktivitas kerja dilingkungan kantor.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 290603);
