INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62169676', 62169676, 'analyze_legacy', 'Kementerian Kesehatan', 'central', 'BALAI LABORATORIUM KESEHATAN MASYARAKAT BANJARNEGARA', 'Belanja Langganan Daya dan Jasa Lainnya', 'Jasa Lainnya', 'Pengadaan Langsung', 'Jawa Tengah, Banjarnegara (Kab.)', 9200000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1 Paket', '1. Langganan aplikasi online meeting ( 1, THN, @ 3000000 ); 2. Langganan hosting dan domain ( 1, THN, @ 1200000 ); 3. Langganan Absensi Online ( 1, THN, @ 5000000 );', '1. Langganan aplikasi online meeting Platform komunikasi daring yang memungkinkan pengguna untuk melakukan pertemuan, presentasi, dan kolaborasi melalui video dan audio melalui internet sehingga memudahkan komunikasi dalam rapat yang dilakukan secara online 2. Langganan hosting dan domain Langganan hosting dan domain yaitu layanan penyimpanan dan pengelolaan data, aplikasi, dan situs web di server yang terhubung ke internet dapat diakses oleh pengguna dari seluruh dunia. Langganan hosting dan domain yang handal dan lengkap adalah investasi penting untuk mendukung operasi Balai Labkesmas Banjarnegara. Dengan layanan ini, kami dapat meningkatkan kualitas pelayanan kepada masyarakat, melindungi data penting, dan memastikan operasi yang efisien dan efektif. 3. Langganan Absensi Online Aplikasi absensi online karyawan via ponsel untuk membantu manajemen absensi perusahaan. Adapun penggunaan langganan jasa aplikasi tersebut diperlukan sebagai sarana untuk merekap kehadiran pegawai yang belum bisa diakomodir oleh aplikasi e-office. Hal tersebut karena keterbatasan sarana dan prasarana, serta jaringan internet yang belum memadai maupun struktur geografis Kabupaten Banjarnegara yang didominasi oleh pegunungan. Sebagai tambahan, langganan jasa aplikasi tersebut tidak berbeda halnya dengan langganan jasa lainnya seperti internet dan Listrik yang menggunakan jasa pihak ketiga, sehingga tidak memerlukan server khusus atau tersendiri.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 290876);
