INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62921378', 62921378, 'analyze_legacy', 'Kab. Bandung', 'kabkota', 'DINAS PEKERJAAN UMUM DAN TATA RUANG', 'Peningkatan Jalan jalur sindanglaya legok nyenang ( KP. Cilaja Rt 03/02), Kab. Bandung Ds Mekarmanik Kec Cimenyan', 'Pekerjaan Konstruksi', 'Pengadaan Langsung', 'Jawa Barat, Bandung (Kab.)', 120800000, 'January 2026', 'APBD', 1, 1, '192.05 m2', 'Persiapan Pekerjaan Lapangan : 1) Persiapan Tujuan dari tahap persiapan adalah untuk mengumpulkan informasi awal mengenai kondisi, lalulintas serta lingkungan. 2) Survey Lapangan Tujuan survey adalah untuk mengumpulkan data-data awal berdasarkan aspek-aspek yang diperlukan yang akan digunakan sebagai dasar/referensi', 'Pekerjaan membangun kembali struktur jalan dengan perbaikan tanah dasar, pondasi, dan pelapisan perkerasan baru sesuai standar teknis.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 295402);
INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65227281', 65227281, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'Jasa Konsultan Junior Penyusunan Kajian Kebijakan Pelaksanaan Pengendalian Perencanaan dan Pelaksanaan Pembangunan', 'Jasa Konsultansi', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 99600000, 'February 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '00', 'Lingkup pekerjaan Jasa Konsultan Junior Penyusunan Kajian Kebijakan Pelaksanaan Pengendalian Perencanaan dan Pelaksanaan Pembangunan meliputi beberapa kegiatan yang mencakup: 1) Asistensi Penyusunan Rancangan Peraturan Menteri PPN/Kepala Bappenas tentang Pengendalian dan Evaluasi Pembangunan; 2) Asistensi Penyusunan Prosedur Evaluasi Pembangunan Jangka Menengah sebagai turunan dari Peraturan Menteri PPN/Kepala Bappenas yang telah disusun; 3) Asistensi Penyusunan Prosedur Perencanaan, Pengendalian Pelaksanaan, dan Pelaporan Akuntabilitas Kinerja Pembangunan Nasional; serta 4) Monitoring dan Evaluasi Implementasi Peraturan Menteri PPN/Kepala Bappenas tentang Pengendalian dan Evaluasi Pembangunan termasuk prosedur turunannya. Adapun kegiatan tersebut terdiri atas tahapan persiapan penyusunan, proses penyusunan dan pembahasan draf, hingga penyampaian hasil akhir dokumen Peraturan Menteri PPN/Kepala Bappenas.', 'Keluaran kegiatan dari lingkup pekerjaan Jasa Konsultan Junior Penyusunan Kajian Kebijakan Pelaksanaan Pengendalian Perencanaan dan Pelaksanaan Pembangunan adalah Laporan Penyusunan Kajian Kebijakan Pelaksanaan Pengendalian Perencanaan dan Pelaksanaan Pembangunan dengan waktu penyelesaian selama 11 bulan. Jasa Konsultan Junior Penyusunan Kajian Kebijakan Pelaksanaan Pengendalian Perencanaan dan Pelaksanaan Pembangunan berperan dalam mendukung pekerjaan Direktorat Sistem dan Manajemen Risiko, dengan rincian keluaran setiap terminnya sebagai berikut. No Periode Keluaran per Termin 1 Termin 1 Laporan hasil pendalaman substansi Rancangan Peraturan Menteri PPN/Kepala Bappenas dan kerangka substansi Prosedur Evaluasi Pembangunan Jangka Menengah 2 Termin 2 Laporan Draf Awal Rancangan Peraturan Menteri PPN/Kepala Bappenas dan Petunjuk Pelaksanaan sebagai turunan Permen serta Kerangka substansi Prosedur Perencanaan, Pengendalian Pelaksanaan, dan Pelaporan Akuntabilitas Kinerja Pembangunan Nasional 3 Termin 3 Laporan Draf Rancangan Peraturan Menteri PPN/Kepala Bappenas dan Petunjuk Pelaksanaan sebagai turunan Permen serta Draf Awal Prosedur Perencanaan, Pengendalian Pelaksanaan, dan Pelaporan Akuntabilitas Kinerja Pembangunan Nasional 4 Termin 4 Laporan Draf Rancangan Peraturan Menteri PPN/Kepala Bappenas dan Petunjuk Pelaksanaan sebagai turunan Permen serta Draf Prosedur Perencanaan, Pengendalian Pelaksanaan, dan Pelaporan Akuntabilitas Kinerja Pembangunan Nasional 5 Termin 5 Laporan Dokumen Peraturan Menteri PPN/Kepala Bappenas hasil harmonisasi dan Prosedur Evaluasi Pembangunan Jangka Menengah sebagai turunan Permen serta Draf Prosedur Perencanaan, Pengendalian Pelaksanaan, dan Pelaporan Akuntabilitas Kinerja Pembangunan Nasional 6 Termin 6 Laporan Penyusunan Kajian Kebijakan Pelaksanaan Pengendalian Perencanaan dan Pelaksanaan Pembangunan', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 295403);
